// ============================================================
// EDIT the recipientEmail constant below to set who receives
// the report. Everything else is built dynamically from the
// aggregated report data produced by the previous node.
//
// v2 — mobile-safe rewrite (same fix as the Threads version):
//  - Summary tiles and post rows now use HTML <table> cells
//    instead of CSS flexbox, since mobile mail apps (Gmail in
//    particular) render flex unreliably inside emails.
//  - The old 9-column data table (Date/Caption/Reach/Views/...)
//    is replaced with stacked post "cards" — no columns to
//    squeeze onto a ~360px phone screen, no horizontal scroll.
//  - Background now uses a real gradient behind the whole email,
//    not just the header.
//  - Added <meta name="color-scheme"> so Gmail dark mode doesn't
//    invert the gradient colors.
//  - Top Performer reason badges (Most Viewed / Most Liked / etc)
//    are preserved, just rendered inside a table-based card.
//  - All data logic (leaders, scoring, breakdowns) is unchanged.
// ============================================================
const recipientEmail = 'user@example.com';

const data = $input.first().json;
const account = data.account;
const summary = data.summary;
const photoBreakdown = data.photoBreakdown;
const videoBreakdown = data.videoBreakdown;
const posts = data.posts || [];
const reportDateLabel = data.reportDateLabel;
const rangeStartLabel = data.rangeStartLabel;
const rangeEndLabel = data.rangeEndLabel;
const profileError = data.profileError;
const mediaError = data.mediaError;

function esc(str) {
  return String(str == null ? '' : str)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}
function num(n) { return Number(n || 0).toLocaleString('en-US'); }
function fmtShort(iso) {
  const dt = DateTime.fromISO(iso);
  return dt.isValid ? dt.toFormat('LLL d, HH:mm') : (iso || 'N/A');
}
function truncate(str, len) {
  const s = String(str == null ? '' : str).replace(/\s+/g, ' ').trim();
  return s.length > len ? s.slice(0, len) + '\u2026' : (s || '(no caption)');
}
function chunk(arr, size) {
  const out = [];
  for (let i = 0; i < arr.length; i += size) out.push(arr.slice(i, i + size));
  return out;
}
function metricSpan(label, value) {
  return `<span class="metric"><b>${num(value)}</b> ${esc(label)}</span>`;
}

const emailSubject = `${account.name} \u00b7 Instagram Insights Report \u00b7 ${reportDateLabel} \u00b7 ${summary.totalPosts} post${summary.totalPosts === 1 ? '' : 's'}`;

// ---------- Summary tiles (3-column TABLE grid — no flexbox) ----------
const tileDefs = [
  ['Total Posts', summary.totalPosts],
  ['Photo Posts', summary.totalPhotoPosts],
  ['Video Posts', summary.totalVideoPosts],
  ['Total Followers', summary.totalFollowers],
  ['Total Interactions', summary.totalInteractions],
  ['Total Likes', summary.totalLikes],
  ['Total Comments', summary.totalComments],
  ['Total Shares', summary.totalShares],
  ['Total Saves', summary.totalSaves],
  ['Total Views', summary.totalViews]
];

function tileCell([label, value]) {
  return `
        <td class="tile" width="33.33%" valign="top">
          <div class="tile-inner">
            <div class="tile-value">${num(value)}</div>
            <div class="tile-label">${esc(label)}</div>
          </div>
        </td>`;
}

const tileRows = chunk(tileDefs, 3).map(row => {
  const cells = row.map(tileCell).join('');
  const pad = '<td class="tile" width="33.33%">&nbsp;</td>'.repeat(3 - row.length);
  return `<tr>${cells}${pad}</tr>`;
}).join('');

// ---------- Top Performing Posts ----------
// A post qualifies for this section only if it is the single highest
// post that day on at least one of: views, likes, comments, shares,
// saves, or total interactions. If every post is at zero across all
// of these metrics, no post qualifies and the section is hidden.
const metricDefs = [
  ['views', p => p._views || 0, '\ud83d\udc41\ufe0f Most Viewed'],
  ['likes', p => p._likes || 0, '\u2764\ufe0f Most Liked'],
  ['comments', p => p._comments || 0, '\ud83d\udcac Most Commented'],
  ['shares', p => p._shares || 0, '\ud83d\udd01 Most Shared'],
  ['saved', p => p._saved || 0, '\ud83d\udccc Most Saved'],
  ['interactions', p => p._interactions || 0, '\u2b50 Most Interactions']
];
function score(p) {
  return p._interactions || ((p._likes||0) + (p._comments||0) + (p._shares||0) + (p._saved||0) + (p._views||0));
}
const leaderIds = new Set();
const reasonsById = {};
metricDefs.forEach(([key, fn, label]) => {
  const max = posts.reduce((m, p) => Math.max(m, fn(p)), 0);
  if (max > 0) {
    posts.filter(p => fn(p) === max).forEach(p => {
      leaderIds.add(p.id);
      (reasonsById[p.id] = reasonsById[p.id] || []).push(label);
    });
  }
});
const topPerformers = leaderIds.size > 0
  ? posts.filter(p => leaderIds.has(p.id)).sort((a, b) => score(b) - score(a)).slice(0, 6)
  : [];

function typeLabel(t) { return t === 'photo' ? 'Photo' : t === 'video' ? 'Video/Reel' : 'Post'; }

function topCard(p, i) {
  const reasons = (reasonsById[p.id] || []).map(r => `<span class="reason">${esc(r)}</span>`).join('');
  const metrics = [
    p._type === 'video' ? metricSpan('Views', p._views) : '',
    metricSpan('Reach', p._reach),
    metricSpan('Likes', p._likes),
    metricSpan('Comments', p._comments),
    metricSpan('Shares', p._shares),
    metricSpan('Saves', p._saved)
  ].join('');
  return `
    <table class="top-card" role="presentation" width="100%" cellpadding="0" cellspacing="0">
      <tr>
        <td class="top-rank" width="34" valign="top">#${i + 1}</td>
        <td valign="top">
          <div class="top-meta-row">
            <span class="badge badge-${esc(p._type)}">${esc(typeLabel(p._type))}</span>
            <span class="top-time">${fmtShort(p.timestamp)}</span>
          </div>
          <div class="top-reasons">${reasons}</div>
          <p class="top-caption">${esc(truncate(p.caption, 140))}</p>
          <div class="top-metrics">${metrics}</div>
          ${p.permalink ? `<a class="post-link" href="${esc(p.permalink)}" target="_blank" rel="noopener noreferrer">View on Instagram \u2192</a>` : ''}
        </td>
      </tr>
    </table>`;
}

const topPerformersSection = topPerformers.length ? `
  <div class="section">
    <h2>\ud83c\udfc6 Top Performing Posts</h2>
    ${topPerformers.map(topCard).join('')}
  </div>` : '';

// ---------- Compact breakdown stat boxes (table row, no flexbox) ----------
function statBoxes(b, showViews) {
  const items = [];
  if (showViews) items.push(['Views', b.totalViews]);
  items.push(['Reach', b.totalReach]);
  items.push(['Interact.', b.totalInteractions]);
  items.push(['Likes', b.totalLikes]);
  items.push(['Comments', b.totalComments]);
  items.push(['Shares', b.totalShares]);
  items.push(['Saves', b.totalSaves]);
  const w = (100 / items.length).toFixed(2) + '%';
  const cells = items.map(([label, value]) => `
        <td class="stat-box" width="${w}">
          <div class="stat-value">${num(value)}</div>
          <div class="stat-label">${esc(label)}</div>
        </td>`).join('');
  return `<table class="stat-line" role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>${cells}</tr></table>`;
}

// ---------- Photo / Video posts as stacked cards (replaces the old 9-col table) ----------
function postCard(p) {
  const metrics = [
    ['Reach', p._reach],
    p._type === 'video' ? ['Views', p._views] : null,
    ['Likes', p._likes],
    ['Comments', p._comments],
    ['Shares', p._shares],
    ['Saves', p._saved]
  ].filter(Boolean).map(([label, value]) => metricSpan(label, value)).join('');

  return `
    <table class="post-card" role="presentation" width="100%" cellpadding="0" cellspacing="0">
      <tr>
        <td>
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0">
            <tr>
              <td class="post-card-date" align="left">${fmtShort(p.timestamp)}</td>
              <td align="right">${p.permalink ? `<a class="post-link" href="${esc(p.permalink)}" target="_blank" rel="noopener noreferrer">View \u2192</a>` : ''}</td>
            </tr>
          </table>
          <p class="post-card-caption">${esc(truncate(p.caption, 100))}</p>
          <div class="post-card-metrics">${metrics}</div>
        </td>
      </tr>
    </table>`;
}

function postSection(title, list, breakdown, showViews) {
  if (!list.length) {
    return `
  <div class="section">
    <h2>${esc(title)} (0)</h2>
    <p class="empty-state">No ${esc(title.toLowerCase())} were published in this reporting period.</p>
  </div>`;
  }
  return `
  <div class="section">
    <h2>${esc(title)} (${num(list.length)})</h2>
    ${statBoxes(breakdown, showViews)}
    <div class="post-list">
      ${list.map(postCard).join('')}
    </div>
  </div>`;
}

const photoPosts = posts.filter(p => p._type === 'photo');
const videoPosts = posts.filter(p => p._type === 'video');
const photoSectionHtml = postSection('Photo Cards', photoPosts, photoBreakdown, false);
const videoSectionHtml = postSection('Video Cards', videoPosts, videoBreakdown, true);

const errorBanner = (profileError || mediaError)
  ? `<div class="error-banner">\u26a0\ufe0f ${esc((profileError && profileError.message) || (mediaError && mediaError.message) || 'Some data could not be loaded from the Instagram API.')}</div>`
  : '';

const emailHtml = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<meta name="color-scheme" content="light">
<meta name="supported-color-schemes" content="light">
<title>${esc(account.name)} \u2014 Instagram Insights Report \u2014 ${esc(reportDateLabel)}</title>
<style>
  body{margin:0;padding:0;background:#eef1f7;color:#1a1a2e;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;-webkit-text-size-adjust:100%;}
  table{border-collapse:collapse;}
  img{border:0;display:block;}
  a{color:#2ecc71;}
  .bg-wrap{background:linear-gradient(180deg,#f7f8fc 0%,#eef1f7 55%,#e8ebf2 100%);padding:16px 0;}
  .wrap{max-width:640px;margin:0 auto;padding:0 12px;width:100%;box-sizing:border-box;}
  .header{border-radius:18px;padding:20px 16px;background:linear-gradient(120deg,#ff5f6d 0%,#ffc371 45%,#2ecc71 100%);}
  .avatar{width:52px;height:52px;border-radius:50%;object-fit:cover;background:#ffffff;border:2px solid rgba(255,255,255,0.85);}
  .header h1{margin:0;font-size:17px;line-height:1.3;color:#ffffff;text-shadow:0 1px 2px rgba(0,0,0,0.15);}
  .header p{margin:4px 0 0;color:rgba(255,255,255,0.92);font-size:12px;}
  .section{background:#ffffff;border-radius:14px;padding:14px;margin-top:12px;box-shadow:0 1px 2px rgba(20,20,40,0.06);}
  .section h2{margin:0 0 10px;font-size:13px;color:#1a1a2e;font-weight:700;}
  .tile{padding:4px;}
  .tile-inner{background:linear-gradient(160deg,#fef6f0,#f0fbf4);border:1px solid #eef0f4;border-radius:10px;padding:10px 4px;text-align:center;}
  .tile-value{font-size:15px;font-weight:800;color:#1a1a2e;white-space:nowrap;}
  .tile-label{font-size:9px;color:#6b7280;margin-top:3px;line-height:1.3;}
  .top-card{border:1px solid #eef0f4;border-left:3px solid #ff5f6d;border-radius:10px;margin-bottom:8px;}
  .top-card td{padding:10px 12px;}
  .top-rank{font-weight:800;color:#ff5f6d;font-size:13px;}
  .top-meta-row{font-size:10.5px;}
  .badge{background:#eef0ff;color:#4b5bd6;border-radius:999px;padding:2px 8px;font-size:9.5px;font-weight:700;display:inline-block;}
  .top-time{color:#9ca3af;margin-left:6px;}
  .top-reasons{margin:5px 0 0;}
  .reason{background:#fff4e5;color:#b45309;border-radius:999px;padding:2px 7px;font-size:9px;font-weight:700;margin-right:4px;display:inline-block;margin-bottom:3px;}
  .top-caption{font-size:12.5px;margin:6px 0;word-break:break-word;}
  .top-metrics{font-size:10.5px;color:#374151;}
  .metric{display:inline-block;margin:0 8px 4px 0;white-space:nowrap;}
  .metric b{color:#1a1a2e;}
  .post-link{font-size:11.5px;color:#2ecc71;text-decoration:none;font-weight:700;white-space:nowrap;}
  .stat-line{margin-bottom:10px;border-bottom:1px solid #f0f1f5;padding-bottom:2px;}
  .stat-box{padding:6px 2px;text-align:center;border-right:1px solid #f0f1f5;}
  .stat-box:last-child{border-right:0;}
  .stat-value{font-size:12px;font-weight:700;color:#1a1a2e;}
  .stat-label{font-size:8px;color:#6b7280;margin-top:2px;}
  .post-list{border-top:1px solid #f0f1f5;margin-top:4px;}
  .post-card{border-bottom:1px solid #f0f1f5;}
  .post-card td{padding:10px 0;}
  .post-card-date{font-size:10.5px;color:#9ca3af;white-space:nowrap;}
  .post-card-caption{font-size:12px;margin:5px 0;word-break:break-word;color:#374151;}
  .post-card-metrics{font-size:10.5px;color:#4b5563;}
  .empty-state{color:#9ca3af;text-align:center;padding:16px;font-size:12.5px;}
  .error-banner{background:#fef2f2;color:#b91c1c;border-radius:10px;padding:10px 14px;font-size:12px;margin-top:12px;}
  footer{text-align:center;color:#9ca3af;font-size:10.5px;padding:18px 0;}
  @media (max-width:480px){
    .wrap{padding:0 8px;}
    .header{padding:16px 12px;}
    .header h1{font-size:15.5px;}
    .tile-value{font-size:13px;}
    .tile-label{font-size:8px;}
    .top-caption{font-size:12px;}
    .post-card-caption{font-size:11.5px;}
    .stat-value{font-size:11px;}
    .stat-label{font-size:7.5px;}
  }
</style>
</head>
<body>
<div class="bg-wrap">
  <div class="wrap">

    <div class="header">
      <table role="presentation" width="100%" cellpadding="0" cellspacing="0">
        <tr>
          <td width="60" valign="middle"><img class="avatar" src="${esc(account.profilePic)}" alt="${esc(account.name)} logo"></td>
          <td valign="middle" style="padding-left:12px;">
            <h1>${esc(account.name)}${account.username ? ` <span style="color:rgba(255,255,255,0.85);font-weight:400;">@${esc(account.username)}</span>` : ''}</h1>
            <p>Instagram Insights Report \u2014 ${esc(reportDateLabel)}</p>
          </td>
        </tr>
      </table>
    </div>

    ${errorBanner}

    <div class="section">
      <h2>Summary</h2>
      <table class="tiles" role="presentation" width="100%" cellpadding="0" cellspacing="0">
        ${tileRows}
      </table>
    </div>

    ${topPerformersSection}

    ${photoSectionHtml}

    ${videoSectionHtml}

    <footer>Generated automatically for @${esc(account.username || account.name)} \u00b7 ${esc(reportDateLabel)}</footer>
  </div>
</div>
</body>
</html>`;

return [{
  json: {
    emailSubject,
    emailHtml,
    recipientEmail
  }
}];

// ============================================================
// Filters today's Instagram posts into the target date range and
// splits them into one item per post so the next HTTP Request
// node can fetch per-post insights (one call per item). If there
// are zero posts in range, outputs a single "_noPosts" sentinel
// item instead, so the rest of the workflow (and the account loop)
// still completes and a report/email is still generated.
// ============================================================

const config = $('⚙️ Config: Page & Date').first().json;
const profileResp = $('Get Instagram Profile').first().json;
const mediaResp = $('Get Instagram Media').first().json;

// --- Current total followers ---
// The Instagram Graph API exposes this directly as a field on the IG
// User node (fields=followers_count), so no separate insights call
// is needed — it's the account's current total, not a daily delta.
const totalFollowers = (profileResp && typeof profileResp.followers_count === 'number')
  ? profileResp.followers_count
  : 0;

const tzOffset = Number(config.timezoneOffsetHours || 0);
const targetYear = Number(config.targetYear);
const targetMonth = Number(config.targetMonth);
const targetDay = Number(config.targetDay);

const localStart = DateTime.fromObject(
  { year: targetYear, month: targetMonth, day: targetDay, hour: 0, minute: 0, second: 0 },
  { zone: 'utc' }
).minus({ hours: tzOffset });
const localEnd = localStart.plus({ days: 1 });

const profileError = profileResp && profileResp.error ? profileResp.error : null;
const mediaError = mediaResp && mediaResp.error ? mediaResp.error : null;

const account = {
  id: (profileResp && profileResp.id) ? profileResp.id : config.pageId,
  username: (profileResp && profileResp.username) ? profileResp.username : config.pageName,
  name: (profileResp && profileResp.name) ? profileResp.name : config.pageName,
  profilePic: (profileResp && profileResp.profile_picture_url) ? profileResp.profile_picture_url : ''
};

const rawPosts = (mediaResp && Array.isArray(mediaResp.data)) ? mediaResp.data : [];

function inRange(iso) {
  if (!iso) return false;
  const dt = DateTime.fromISO(iso);
  if (!dt.isValid) return false;
  return dt >= localStart && dt < localEnd;
}
function classify(p) {
  const t = (p.media_type || '').toUpperCase();
  if (t === 'VIDEO') return 'video';
  if (t === 'IMAGE' || t === 'CAROUSEL_ALBUM') return 'photo';
  return 'other';
}

const todaysPosts = rawPosts
  .filter(p => inRange(p.timestamp))
  .sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp))
  .map(p => ({ ...p, _type: classify(p) }));

let reportDateLabel;
try {
  reportDateLabel = DateTime.fromObject({ year: targetYear, month: targetMonth, day: targetDay }).toFormat('d LLLL yyyy');
} catch (e) {
  reportDateLabel = `${targetYear}-${targetMonth}-${targetDay}`;
}
const rangeStartLabel = localStart.plus({ hours: tzOffset }).toFormat('d LLLL yyyy, h:mm a');
const rangeEndLabel = localEnd.plus({ hours: tzOffset }).minus({ seconds: 1 }).toFormat('d LLLL yyyy, h:mm a');

const base = {
  account, reportDateLabel, rangeStartLabel, rangeEndLabel,
  profileError, mediaError,
  totalFollowers,
  apiVersion: config.apiVersion,
  accessToken: config.accessToken
};

if (todaysPosts.length === 0) {
  return [{ json: { ...base, _noPosts: true } }];
}

return todaysPosts.map(p => ({ json: { ...base, ...p, _noPosts: false } }));

const original = $('📋 Filter & Split Posts').item.json;
const resp = $json;

const rows = Array.isArray(resp && resp.data) ? resp.data : [];
const m = {};
rows.forEach(row => {
  const val = (row.values && row.values[0] && typeof row.values[0].value === 'number')
    ? row.values[0].value
    : (row.total_value && typeof row.total_value.value === 'number' ? row.total_value.value : 0);
  m[row.name] = val;
});

const likes = m.likes || 0;
const comments = m.comments || 0;
const shares = m.shares || 0;
const saved = m.saved || 0;
const reach = m.reach || 0;
const views = m.views || 0; // only requested/returned for video & reel posts
const totalInteractions = m.total_interactions || (likes + comments + shares + saved);
const insightsError = resp && resp.error ? resp.error : null;

return {
  json: {
    ...original,
    _likes: likes,
    _comments: comments,
    _shares: shares,
    _saved: saved,
    _reach: reach,
    _views: views,
    _interactions: totalInteractions,
    _insightsError: insightsError
  }
};

// ============================================================
// Consumes every item coming out of "🔀 Combine Posts" (either
// N real posts each carrying their own Instagram insights, or a
// single "_noPosts" sentinel item for zero-post days) and builds
// the full dynamic report data set consumed by
// "🎨 Build HTML Email Report".
// NOTE: Meta deprecated the standalone "impressions" metric for
// most IG media types, so "reach" is used as the closest available
// impressions-style signal throughout this report.
// ============================================================

const items = $input.all().map(i => i.json);
const first = items[0] || {};

const account = first.account;
const reportDateLabel = first.reportDateLabel;
const rangeStartLabel = first.rangeStartLabel;
const rangeEndLabel = first.rangeEndLabel;
const profileError = first.profileError;
const mediaError = first.mediaError;
const totalFollowers = typeof first.totalFollowers === 'number' ? first.totalFollowers : 0;

const posts = items.filter(i => !i._noPosts);

function sum(arr, fn) { return arr.reduce((acc, p) => acc + fn(p), 0); }

const photoPosts = posts.filter(p => p._type === 'photo');
const videoPosts = posts.filter(p => p._type === 'video');

const summary = {
  totalPosts: posts.length,
  totalPhotoPosts: photoPosts.length,
  totalVideoPosts: videoPosts.length,
  totalInteractions: sum(posts, p => p._interactions || 0),
  totalLikes: sum(posts, p => p._likes || 0),
  totalComments: sum(posts, p => p._comments || 0),
  totalShares: sum(posts, p => p._shares || 0),
  totalSaves: sum(posts, p => p._saved || 0),
  totalViews: sum(posts, p => p._views || 0),
  totalFollowers
};

const photoBreakdown = {
  totalPhotoPosts: photoPosts.length,
  totalInteractions: sum(photoPosts, p => p._interactions || 0),
  totalLikes: sum(photoPosts, p => p._likes || 0),
  totalComments: sum(photoPosts, p => p._comments || 0),
  totalShares: sum(photoPosts, p => p._shares || 0),
  totalSaves: sum(photoPosts, p => p._saved || 0),
  totalReach: sum(photoPosts, p => p._reach || 0)
};

const videoBreakdown = {
  totalVideoPosts: videoPosts.length,
  totalViews: sum(videoPosts, p => p._views || 0),
  totalInteractions: sum(videoPosts, p => p._interactions || 0),
  totalLikes: sum(videoPosts, p => p._likes || 0),
  totalComments: sum(videoPosts, p => p._comments || 0),
  totalShares: sum(videoPosts, p => p._shares || 0),
  totalSaves: sum(videoPosts, p => p._saved || 0),
  totalReach: sum(videoPosts, p => p._reach || 0)
};

function score(p) {
  return p._interactions || ((p._likes||0) + (p._comments||0) + (p._shares||0) + (p._saved||0) + (p._views||0));
}

const topPosts = [...posts].sort((a, b) => score(b) - score(a)).slice(0, 10);
const insightsErrorCount = posts.filter(p => p._insightsError).length;

return [{
  json: {
    account, reportDateLabel, rangeStartLabel, rangeEndLabel,
    summary, photoBreakdown, videoBreakdown, topPosts, posts,
    insightsErrorCount, profileError, mediaError
  }
}];
